import{_ as e,o as t,c as i,a3 as l}from"./chunks/framework.B9qR_F1m.js";const p=JSON.parse('{"title":"语文","description":"古代文学、现代文学与写作方法的学习笔记，聚焦文本细读与表达训练。","frontmatter":{"title":"语文","subject":"chinese","subjectLabel":"语文","description":"古代文学、现代文学与写作方法的学习笔记，聚焦文本细读与表达训练。"},"headers":[],"relativePath":"subjects/chinese/index.md","filePath":"subjects/chinese/index.md","lastUpdated":null}'),r={name:"subjects/chinese/index.md"};function o(s,a,n,c,h,d){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="语文" tabindex="-1">语文 <a class="header-anchor" href="#语文" aria-label="Permalink to &quot;语文&quot;">​</a></h1><p>语文部分按 <strong>古代文学 / 现代文学 / 写作方法</strong> 三条线整理。内容取舍上偏向&quot;可复用的方法&quot;： 能直接套用到阅读题与作文里的框架、术语和答题句式。</p><h2 id="分类导航" tabindex="-1">分类导航 <a class="header-anchor" href="#分类导航" aria-label="Permalink to &quot;分类导航&quot;">​</a></h2><h3 id="古代文学" tabindex="-1">古代文学 <a class="header-anchor" href="#古代文学" aria-label="Permalink to &quot;古代文学&quot;">​</a></h3><ul><li><a href="./classical/poetry-appreciation">古诗词鉴赏方法（写作模板）</a> —— 四步读诗法与答题模板</li><li><a href="./classical/classical-words">文言实词与虚词</a> —— 高频实词、18 个常见虚词用法</li></ul><h3 id="现代文学" tabindex="-1">现代文学 <a class="header-anchor" href="#现代文学" aria-label="Permalink to &quot;现代文学&quot;">​</a></h3><ul><li><a href="./modern/prose-reading">现代散文阅读</a> —— 梳理线索、概括主旨、品析语言</li></ul><h3 id="写作方法" tabindex="-1">写作方法 <a class="header-anchor" href="#写作方法" aria-label="Permalink to &quot;写作方法&quot;">​</a></h3><ul><li><a href="./writing/argumentative-essay">议论文结构</a> —— 立意、结构、论据与语言</li></ul><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><ul><li>鉴赏类笔记统一采用「<strong>方法 → 示例 → 练习</strong>」三步结构，便于复习时只看方法；</li><li>文言类笔记按词条卡片形式记录，一个义项配一个课本原句；</li><li>写作类笔记给出可套用的结构骨架，但不提供成篇范文，避免背套作。</li></ul><blockquote><p><strong>提示</strong>：引用原文一律使用直角引号「」，与正文的双引号区分开，便于检索时定位原文。</p></blockquote>',12)])])}const _=e(r,[["render",o]]);export{p as __pageData,_ as default};
